import {Run,ROUTES} from './engine.js';
import {Art} from './art.js';
const $=id=>document.getElementById(id);
let run=new Run(0),art=new Art(),scene,accumulator=0,soundOn=false,audio,toastTimer,modalAction,secondaryAction;
let records={};try{const saved=JSON.parse(localStorage.getItem('sunset-skate-v1')||'{}');if(saved&&typeof saved==='object'&&!Array.isArray(saved))records=saved;}catch{}
function saveRecord(){const old=records[run.level.index];records[run.level.index]={stars:Math.max(Number(old?.stars)||0,run.collected.size),completed:true};try{localStorage.setItem('sunset-skate-v1',JSON.stringify(records));}catch{}updateRecord();}
function updateRecord(){const r=records[run.level.index];$('best').textContent=r?.completed?`个人最佳 · ${Number(r.stars)||0} 星 / 已通关`:'个人最佳 · 等你创造';document.querySelectorAll('.route-record').forEach((e,i)=>e.textContent=records[i]?.completed?'✓ 已完成':'');}
function sound(type){if(!soundOn)return;try{audio??=new(window.AudioContext||window.webkitAudioContext)();if(audio.state==='suspended')audio.resume();const tones={jump:[250,500,.12],star:[780,1200,.12],land:[110,60,.07],crash:[190,45,.28],checkpoint:[600,900,.24],win:[500,1400,.6]};const [a,b,d]=tones[type]||tones.star;const osc=audio.createOscillator(),gain=audio.createGain();osc.type=type==='crash'?'sawtooth':'sine';osc.frequency.setValueAtTime(a,audio.currentTime);osc.frequency.exponentialRampToValueAtTime(b,audio.currentTime+d);gain.gain.setValueAtTime(.07,audio.currentTime);gain.gain.exponentialRampToValueAtTime(.001,audio.currentTime+d);osc.connect(gain);gain.connect(audio.destination);osc.start();osc.stop(audio.currentTime+d);}catch{}}
function toast(message,duration=2200){$('toast').textContent=message;$('toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('show'),duration);}
function updateHud(){ $('stars').textContent=String(run.collected.size).padStart(2,'0');$('distance').textContent=Math.floor(run.progress*run.level.length/10);$('progress-fill').style.width=`${run.progress*100}%`;$('charge-fill').style.width=`${run.charge*100}%`;$('charge-label').textContent=run.holding?(run.charge>=1?'蓄力满了，松开！':'蓄力中… 松开起跳'):'轻点小跳 · 长按蓄力';$('jump').classList.toggle('charging',run.holding);}
function hideModal(){$('modal').hidden=true;}
function showModal({eyebrow,title,copy,primary,secondary,action,second,stats=false}){run.cancelInput();$('modal-eyebrow').textContent=eyebrow;$('modal-title').textContent=title;$('modal-copy').textContent=copy;$('modal-primary').textContent=primary;$('modal-secondary').textContent=secondary;modalAction=action;secondaryAction=second;$('result-stats').hidden=!stats;if(stats)$('result-stats').innerHTML=`<div><b>${run.collected.size}<small> / ${run.level.stars.length}</small></b><span>收集星星</span></div><div><b>${run.deaths}</b><span>摔倒次数</span></div>`;$('modal').hidden=false;$('play-controls').hidden=true;$('pause').disabled=true;requestAnimationFrame(()=>$('modal-primary').focus({preventScroll:true}));}
function start(){hideModal();run.reset();run.start();art=new Art();art.camera=0;accumulator=0;$('cover').hidden=true;$('play-controls').hidden=false;$('pause').disabled=false;$('start').blur();toast('前方路障 · 轻点空格，松开起跳',3500);updateHud();}
function retry(){run.retry();art.camera=Math.max(0,run.x-200);art.particles=[];accumulator=0;hideModal();$('play-controls').hidden=false;$('pause').disabled=false;toast(run.checkpoint.x>160?'从检查点出发 · 再来一次':'慢慢来，起跳前留一点距离');$('modal-primary').blur();}
function resume(){hideModal();run.resume();accumulator=0;$('play-controls').hidden=false;$('pause').disabled=false;$('pause').textContent='Ⅱ';$('modal-primary').blur();}
function pause(){if(run.state==='paused'){resume();return;}if(run.state!=='playing')return;run.pause();showModal({eyebrow:'TAKE A BREATHER',title:'风景值得慢一点。',copy:'你的滑板就在这里，准备好再出发。',primary:'继续滑行 →',secondary:'重新开始这条路线',action:resume,second:start});}
function selectRoute(index){run=new Run(index);art=new Art();accumulator=0;hideModal();$('cover').hidden=false;$('play-controls').hidden=true;$('pause').disabled=true;$('route-index').textContent=String(index+1).padStart(2,'0');$('route-name').textContent=ROUTES[index].name;$('route-sub').textContent=ROUTES[index].en;$('game-shell').classList.toggle('night-scene',index===2);document.querySelectorAll('.route-card').forEach((e,i)=>{e.classList.toggle('selected',i===index);e.setAttribute('aria-pressed',i===index?'true':'false');});$('toast').classList.remove('show');updateHud();updateRecord();}
function handleEvents(){for(const e of run.events.splice(0)){sound(e.type);if(e.type==='star')art.burst(e.x,e.y,'#ffe49a',8);if(e.type==='land')art.burst(run.x,run.y,'#d2c596',5);if(e.type==='checkpoint')toast('✓ 检查点已保存 · 放心向前');if(e.type==='crash'){art.burst(run.x,run.y-20,'#f1bf7e',16);showModal({eyebrow:'FALL. GET UP. ROLL AGAIN.',title:'没关系，再来一次。',copy:run.checkpoint.x>160?'已保留到检查点的星星，下一次会更顺。':'在障碍前提前起跳。长按蓄力，松开会跳得更远。',primary:run.checkpoint.x>160?'从检查点继续 ↗':'再试一次 ↗',secondary:'重新开始这条路线',action:retry,second:start});}if(e.type==='win'){saveRecord();showModal({eyebrow:'YOU CAUGHT THE SUNSET',title:'这一程，漂亮！',copy:run.level.index===2?'从落日到蓝调，海岸线已经留下你的轮印。':'海风记住了你的名字。下一段风景，继续一起。',primary:run.level.index<2?'出发，下一条路线 ↗':'再滑一次 ↗',secondary:'重玩这条路线',action:()=>{if(run.level.index<2){selectRoute(run.level.index+1);start();}else start();},second:start,stats:true});}}
}
class CoastScene extends (window.Phaser?.Scene || class {}){
 constructor(){super('coast');}
 create(){scene=this;this.tex=this.textures.createCanvas('world',this.scale.width,this.scale.height);this.img=this.add.image(0,0,'world').setOrigin(0);this.scale.on('resize',size=>{this.tex.setSize(size.width,size.height);this.img.setDisplaySize(size.width,size.height);});this.input.keyboard.addCapture(['SPACE','UP']);this.input.keyboard.on('keydown',event=>{if($('help').open||event.repeat)return;if(['KeyP','Escape'].includes(event.code)){event.preventDefault();pause();return;}if(event.code==='KeyR'&&run.state!=='ready'){event.preventDefault();start();return;}const interactive=event.target instanceof HTMLElement&&event.target.closest('button,a,input,select,textarea');if(interactive)return;if(['Space','ArrowUp'].includes(event.code)){event.preventDefault();if(run.state==='ready'){start();return;}if(run.state==='playing')run.press();}});this.input.keyboard.on('keyup',event=>{if(['Space','ArrowUp'].includes(event.code))run.release();});this.input.on('pointerdown',()=>{if(run.state==='playing')run.press();});this.input.on('pointerup',()=>run.release());this.input.on('pointerupoutside',()=>run.release());this.game.events.on('blur',()=>{if(run.state==='playing')pause();});updateRecord();}
 update(time,delta){const dt=Math.min(delta/1000,.05);if(run.state==='playing'){accumulator+=dt;while(accumulator>=1/120){run.step(1/120);accumulator-=1/120;}}else accumulator=0;handleEvents();art.draw(this.tex.context,this.scale.width,this.scale.height,run,run.state==='paused'?0:dt,run.state==='ready');this.tex.refresh();updateHud();}
}
$('start').onclick=start;$('pause').onclick=pause;$('modal-primary').onclick=()=>modalAction?.();$('modal-secondary').onclick=()=>secondaryAction?.();
$('sound').onclick=()=>{soundOn=!soundOn;$('sound').setAttribute('aria-pressed',String(soundOn));$('sound').setAttribute('aria-label',soundOn?'关闭音效':'开启音效');$('sound').title=soundOn?'关闭音效':'开启音效';sound('star');$('sound').blur();};
$('fullscreen').onclick=async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else if($('game-shell').requestFullscreen)await $('game-shell').requestFullscreen();else toast('当前浏览器不支持全屏，可横屏游玩');}catch{toast('暂时无法全屏，可直接在这里游玩');}$('fullscreen').blur();};
$('jump').addEventListener('pointerdown',e=>{e.preventDefault();$('jump').setPointerCapture(e.pointerId);run.press();});$('jump').addEventListener('pointerup',e=>{e.preventDefault();run.release();});$('jump').addEventListener('pointercancel',()=>run.cancelInput());$('jump').addEventListener('lostpointercapture',()=>run.cancelInput());$('jump').addEventListener('contextmenu',e=>e.preventDefault());
$('jump').addEventListener('keydown',e=>{if(['Space','Enter'].includes(e.code)){e.preventDefault();if(!e.repeat)run.press();}});$('jump').addEventListener('keyup',e=>{if(['Space','Enter'].includes(e.code)){e.preventDefault();run.release();}});
document.querySelectorAll('.route-card').forEach(e=>e.onclick=()=>{selectRoute(Number(e.dataset.route));$('game-shell').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion:reduce)').matches?'instant':'smooth',block:'center'});e.blur();});
$('help-open').onclick=()=>{if(run.state==='playing')pause();$('help').showModal();};$('help-close').onclick=()=>$('help').close();$('help').addEventListener('click',e=>{if(e.target===$('help')){const r=$('help').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$('help').close();}});
document.addEventListener('visibilitychange',()=>{if(document.hidden&&run.state==='playing')pause();});
if(!window.Phaser){$('start').textContent='引擎未加载，请刷新重试';$('start').disabled=true;}else new Phaser.Game({type:Phaser.CANVAS,parent:'game',backgroundColor:'#f7ce9c',banner:false,audio:{noAudio:true},scale:{mode:Phaser.Scale.RESIZE,width:$('game').clientWidth,height:$('game').clientHeight},scene:CoastScene,disableContextMenu:true,fps:{target:60,limit:60},input:{activePointers:2}});
